"]=[[文本输出]],["arg2"]=[[你紧跟丁大侠至此，面前站了数人，为首的男子金冠锦袍，身后簇拥着几个凌府守卫。]],["id"]=[[rlt_szjmjtext22]]},["rlt_szjmjtext23"]={["arg1"]=[[文本输出]],["arg2"]=[[你一走入灵堂发现丁大侠半跪在地，十分痛苦。]],["id"]=[[rlt_szjmjtext23]]},["rlt_szjmjtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[小门紧闭，你听不到里面的声音，却不小心踩到了门口一根树枝发出了声响，还是尽快离开的好。]],["id"]=[[rlt_szjmjtext24]]},["rlt_szjmjtext25"]={["arg1"]=[[文本输出]],["arg2"]=[[你当下脑中一片空白，原一封寻常信笺，不料竟牵扯出这世间奸恶下的无果情缘。都道江湖风雨，哪里有这凌府飘摇？今神功虽成，但与丁大侠这至交之情却再也不复，更何谈让他二人缔结连理。]],["id"]=[[rlt_szjmjtext25]]},["rlt_szjmjtext26"]={["arg1"]=[[文本输出]],["arg2"]=[[情不至深唯恐大梦，情唯至深不恐大梦。你忽然一笑，想着昔日那高楼鲜花：或许汇聚阴曹，二人尚有相见之时，不若助其合葬之愿，再祭上一杯权当喜酒。]],["id"]=[[rlt_szjmjtext26]]},["rlt_szjmjtext27"]={["arg1"]=[[文本输出]],["arg2"]=[[你为二人烧了一柱清香，只愿他们来世岁月安稳。]],["id"]=[[rlt_szjmjtext27]]},["rlt_szjmjtext28"]={["arg1"]=[[文本输出]],["arg2"]=[[你没有物品可以放入。]],["id"]=[[rlt_szjmjtext28]]},["rlt_szjmjtext29"]={["arg1"]=[[文本输出]],["arg2"]=[[气窗外忽传来凌府仆人的叫喊，“小姐没了！”只听四声云板叩响，丁大侠已经煞白了脸。]],["id"]=[[rlt_szjmjtext29]]},["rlt_szjmjtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[当初你摆放的花束已经枯萎，最后一片褶皱的花瓣从花楼上随风飘落。]],["id"]=[[rlt_szjmjtext3]]},["rlt_szjmjtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[你紧追丁大侠，看他往正厅方向去了。]],["id"]=[[rlt_szjmjtext4]]},["rlt_szjmjtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[你被守卫拦住，无法进入。]],["id"]=[[rlt_szjmjtext5]]},["rlt_szjmjtext6"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL疯丫头：别杀我，灵堂......我不知道灵堂在哪。]],["id"]=[[rlt_szjmjtext6]]},["rlt_szjmjtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL丁大侠：......没了？你真的没了？]],["id"]=[[rlt_szjmjtext7]]},["rlt_szjmjtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[你紧跟丁大侠至此，面前站了数人，为首的男子金冠锦袍，身后簇拥着几个凌府守卫。]],["id"]=[[rlt_szjmjtext8]]},["rlt_szjmjtext9"]={["arg1"]=[[文本输出]],["arg2"]=[[凌知府见手下不敌，却丝毫未显惊慌之色，慢步走入灵堂。]],["id"]=[[rlt_szjmjtext9]]},["rlt_szjmjwcbh"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[szjdj5]],["arg3"]=1,["id"]=[[rlt_szjmjwcbh]]},["rlt_szjmjwckc"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[szjdj5]],["arg3"]=-1,["id"]=[[rlt_szjmjwckc]]},["rlt_szjqzcg"]={["arg1"]=[[丁典传功]],["arg2"]=[[szjjgj1]],["arg3"]=[[szjcgwc1;szjmjtext1;szjtjrw3;szjcgts20;delete]],["id"]=[[rlt_sz